export function createPlantMask(profile) {
  const mask = document.createElement('canvas');
  [mask.width, mask.height] = profile.size;
  const ctx = mask.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, mask.width, mask.height);
  const shapes = profile.shapes.map(d => new Path2D(d));
  const stems = profile.stems.map(([width,d]) => [width,new Path2D(d)]);
  ctx.lineJoin = ctx.lineCap = 'round';
  // The red channel clips the moving foreground to the traced plant silhouette.
  ctx.fillStyle = ctx.strokeStyle = '#f00';
  for (const path of shapes) ctx.fill(path);
  for (const [width,path] of stems) { ctx.lineWidth=width; ctx.stroke(path); }
  return mask;
}
